<?php
declare(strict_types=1);
function cancel_schema(PDO $db):void {$db->exec("CREATE TABLE IF NOT EXISTS cancel_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,request_key TEXT UNIQUE NOT NULL,body TEXT NOT NULL,entries TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS deleted_orders(id INTEGER PRIMARY KEY AUTOINCREMENT,fingerprint TEXT NOT NULL,customer TEXT NOT NULL,phone TEXT NOT NULL,payload TEXT NOT NULL,sheet_name TEXT NOT NULL,sheet_id TEXT NOT NULL,row_number INTEGER NOT NULL,sheet_date TEXT NOT NULL,deleted_at TEXT NOT NULL,actor TEXT NOT NULL,version INTEGER NOT NULL,explained INTEGER NOT NULL DEFAULT 0,reviewed INTEGER NOT NULL DEFAULT 0)");}
function cancel_name(string $s):string {return mb_strtoupper(trim(preg_replace('/\s+/u',' ',$s)),'UTF-8');}
function cancel_phone(string $s):string {$s=preg_replace('/\D/','',$s);if(str_starts_with($s,'84')&&strlen($s)>=11)$s='0'.substr($s,2);return $s;}
function cancel_entries(string $body):array {$entries=[];foreach(preg_split('/\R/u',$body) as $line){preg_match_all('/(?<!\d)(?:\+?84|0)[\d .-]{7,18}\d(?!\d)/u',$line,$matches);foreach($matches[0] as $phone){$normalized=cancel_phone($phone);if(strlen($normalized)<9||strlen($normalized)>11)continue;$name=trim(str_replace($phone,'',$line)," \t|:;,-");$name=preg_replace('/^(?:Tên khách|Tên|Khách|Họ tên)\s*[:=-]?\s*/iu','',$name);$name=preg_replace('/\b(?:SĐT|SDT)\s*[:=-]?/iu','',$name);$name=trim($name," \t|:;,-");if($name!=='')$entries[]=['name'=>$name,'phone'=>$normalized];}}return $entries;}
function cancel_save(PDO $db,array $input,array $user):array {cancel_schema($db);$body=trim((string)($input['body']??''));$key=(string)($input['requestKey']??'');if($body===''||mb_strlen($body)>10000||!preg_match('/^[a-f0-9-]{36}$/D',$key))throw new RuntimeException('Kiểm tra nội dung Đơn hủy.',400);$entries=cancel_entries($body);if(!$entries)throw new RuntimeException('Nhập mỗi dòng một tên khách và SĐT đầy đủ.',400);$db->exec('BEGIN IMMEDIATE');try{$q=$db->prepare('SELECT * FROM cancel_messages WHERE request_key=?');$q->execute([$key]);if($old=$q->fetch()){if($old['body']!==$body)throw new RuntimeException('Yêu cầu này đã được lưu với nội dung khác.',409);$db->exec('COMMIT');return ['ok'=>true];}$db->prepare('INSERT INTO cancel_messages(request_key,body,entries,actor,created_at) VALUES(?,?,?,?,?)')->execute([$key,$body,json_encode($entries,JSON_UNESCAPED_UNICODE),$user['username'],gmdate('c')]);$q=$db->prepare('UPDATE deleted_orders SET explained=1 WHERE customer=? AND phone=?');foreach($entries as $e)$q->execute([cancel_name($e['name']),$e['phone']]);if(function_exists('people_audit'))people_audit('cancel_message','Đơn hủy',['entries'=>$entries],$db);$db->exec('COMMIT');return ['ok'=>true];}catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}}
function cancel_rows(array $snapshot):array {$rows=[];foreach($snapshot['sheetOrder']??[] as $sid){$sheet=$snapshot['sheets'][$sid];$map=[];foreach($sheet['cellData'][0]??[] as $c=>$cell){$h=mb_strtoupper(trim((string)($cell['v']??'')),'UTF-8');$map[$h]=(int)$c;}$cols=[$map['TIỀN']??null,$map['TÊN KHÁCH']??null,$map['SĐT']??$map['SDT']??null,$map['ĐỊA CHỈ']??null,$map['SẢN PHẨM / SIZE']??$map['SẢN PHẨM']??null];if(in_array(null,$cols,true))continue;foreach($sheet['cellData']??[] as $r=>$cells){if((int)$r<1||!empty($cells[0]['custom']['victorTotal']))continue;$values=array_map(static fn($c)=>trim((string)($cells[$c]['v']??'')),$cols);if(in_array('',$values,true))continue;$phone=cancel_phone($values[2]);$name=cancel_name($values[1]);$rows[]=['key'=>$name.'|'.$phone,'customer'=>$name,'phone'=>$phone,'values'=>$values,'cells'=>$cells,'sid'=>$sid,'sheet'=>$sheet['name'],'row'=>(int)$r,'rowId'=>$cells[0]['custom']['victorRowId']??''];}}return $rows;}
function cancel_track_deletions(PDO $db,?array $old,array $new,string $actor,int $version):void {
 if(!$old)return;cancel_schema($db);$before=cancel_rows($old);$after=cancel_rows($new);$counts=[];$ids=[];foreach(($new['sheets']??[]) as $s)foreach(($s['cellData']??[]) as $cells){$rid=$cells[0]['custom']['victorRowId']??'';$has=false;foreach($cells as $c=>$cell)if((int)$c>1&&trim((string)($cell['v']??''))!=='')$has=true;if($rid!==''&&$has)$ids[$rid]=true;}foreach($after as $r){$counts[$r['key']]=($counts[$r['key']]??0)+1;if($r['rowId']!=='')$ids[$r['rowId']]=true;}$known=[];foreach($db->query('SELECT entries FROM cancel_messages') as $message)foreach(json_decode($message['entries'],true)??[] as $e)$known[cancel_name($e['name']).'|'.$e['phone']]=true;$insert=$db->prepare('INSERT INTO deleted_orders(fingerprint,customer,phone,payload,sheet_name,sheet_id,row_number,sheet_date,deleted_at,actor,version,explained) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');
 foreach($before as $r){if(($counts[$r['key']]??0)>0){$counts[$r['key']]--;continue;}if($r['rowId']!==''&&isset($ids[$r['rowId']]))continue; // Same row with corrected name/phone is an edit.
  $current=$new['sheets'][$r['sid']]['cellData'][$r['row']]??[];$remaining=0;foreach($current as $c=>$cell)if((int)$c>1&&trim((string)($cell['v']??''))!=='')$remaining++;if($r['rowId']===''&&$remaining>0)continue;
  $date=function_exists('report_sheet_info')?report_sheet_info($r['sheet'])['date']:'';$insert->execute([hash('sha256',json_encode($r['values'])),$r['customer'],$r['phone'],json_encode($r['cells'],JSON_UNESCAPED_UNICODE),$r['sheet'],$r['sid'],$r['row']+1,$date,gmdate('c'),$actor,$version,isset($known[$r['key']])?1:0]);
 }
}
